Here is the commit message:
HADOOP-10622. Shell.runCommand can deadlock. Contributed by
 Gera Shegalov

git-svn-id: https://svn.apache.org/repos/asf/hadoop/common/trunk@1602033 13f79535-47bb-0310-9956-ffa450edef68

Here is the root cause:
The bug was caused by improper handling of the error thread (`errThread`) during the execution of shell commands, which could lead to a deadlock situation if the thread was not joined correctly or if it was interrupted while waiting. The original implementation did not adequately manage interruptions, potentially leaving the thread in a waiting state indefinitely.

Here is the patch:
   /** Run a command */
   private void runCommand() throws IOException { 
     ProcessBuilder builder = new ProcessBuilder(getExecString());
     Timer timeOutTimer = null;
     ShellTimeoutTimerTask timeoutTimerTask = null;
     timedOut = new AtomicBoolean(false);
     completed = new AtomicBoolean(false);

     if (environment != null) {
       builder.environment().putAll(this.environment);
     }
     if (dir != null) {
       builder.directory(this.dir);
     }

     builder.redirectErrorStream(redirectErrorStream);

     if (Shell.WINDOWS) {
       synchronized (WindowsProcessLaunchLock) {
         // To workaround the race condition issue with child processes
         // inheriting unintended handles during process launch that can
         // lead to hangs on reading output and error streams, we
         // serialize process creation. More info available at:
         // http://support.microsoft.com/kb/315939
         process = builder.start();
       }
     } else {
       process = builder.start();
     }

     if (timeOutInterval > 0) {
       timeOutTimer = new Timer("Shell command timeout");
       timeoutTimerTask = new ShellTimeoutTimerTask(
           this);
       //One time scheduling.
       timeOutTimer.schedule(timeoutTimerTask, timeOutInterval);
     }
     final BufferedReader errReader = 
             new BufferedReader(new InputStreamReader(process
                                                      .getErrorStream()));
     BufferedReader inReader = 
             new BufferedReader(new InputStreamReader(process
                                                      .getInputStream()));
     final StringBuffer errMsg = new StringBuffer();

     // read error and input streams as this would free up the buffers
     // free the error stream buffer
     Thread errThread = new Thread() {
       @Override
       public void run() {
         try {
           String line = errReader.readLine();
           while((line != null) && !isInterrupted()) {
             errMsg.append(line);
             errMsg.append(System.getProperty("line.separator"));
             line = errReader.readLine();
           }
         } catch(IOException ioe) {
           LOG.warn("Error reading the error stream", ioe);
         }
       }
     };
     try {
       errThread.start();
     } catch (IllegalStateException ise) { }
     try {
       parseExecResult(inReader); // parse the output
       // clear the input stream buffer
       String line = inReader.readLine();
       while(line != null) { 
         line = inReader.readLine();
       }
       // wait for the process to finish and check the exit code
       exitCode  = process.waitFor();
-      try {
-        // make sure that the error thread exits
-        errThread.join();
-      } catch (InterruptedException ie) {
-        LOG.warn("Interrupted while reading the error stream", ie);
-      }
+      // make sure that the error thread exits
+      joinThread(errThread);
       completed.set(true);
       //the timeout thread handling
       //taken care in finally block
       if (exitCode != 0) {
         throw new ExitCodeException(exitCode, errMsg.toString());
       }
     } catch (InterruptedException ie) {
       throw new IOException(ie.toString());
     } finally {
       if (timeOutTimer != null) {
         timeOutTimer.cancel();
       }
       // close the input stream
       try {
         // JDK 7 tries to automatically drain the input streams for us
         // when the process exits, but since close is not synchronized,
         // it creates a race if we close the stream first and the same
         // fd is recycled.  the stream draining thread will attempt to
         // drain that fd!!  it may block, OOM, or cause bizarre behavior
         // see: https://bugs.openjdk.java.net/browse/JDK-8024521
         //      issue is fixed in build 7u60
         InputStream stdout = process.getInputStream();
         synchronized (stdout) {
           inReader.close();
         }
       } catch (IOException ioe) {
         LOG.warn("Error while closing the input stream", ioe);
       }
